interface UserDao { fun find(id: Long): User?
}

enum class Store { POSTGRES, SQLITE }

fun userDao(store: Store, cfg: Config): UserDao = when (store) {
    Store.POSTGRES -> PgUserDao(cfg.pool)
    Store.SQLITE   -> SqliteUserDao(cfg.path)
}

// decoration without a class hierarchy:
class CachedUserDao(private val base: UserDao) : UserDao by base
